    transform: translateX(-50%) scale(1.02); box-shadow: 0 10px 25px rgba(0, 0, 0, 0.4), 0 0 15px var(--accent-lightblue);
}
.mes[is_user="true"]:active::after { transform: translateX(-50%) scale(0.98); }

@media (max-width: 768px) {
