}

/* --- 8. 全局鼠标指针病娇化 (灵魂光标系统) --- */

/* 默认状态：深蓝色的灵魂爱心 (安静) */
body, html, .mes, .drawer-content, .popup-body, span, div, p {
    cursor: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'%3E%3Cpath fill='%230f2b5b' stroke='%23ffffff' stroke-width='1.5' d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/%3E%3C/svg%3E") 12 12, auto !important;
}

/* 交互悬浮状态：红色的灵魂爱心 (被标记/警告) */
a, button, .menu_button, .mes_button, .drawer-icon, select, option, .ch_name, .mes::after, .title_restorable:hover, summary:hover {
    cursor: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'%3E%3Cpath fill='%23dc143c' stroke='%23ffffff' stroke-width='1.5' d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/%3E%3C/svg%3E") 12 12, pointer !important;
}

/* 点击状态：裂开的灵魂爱心 (破碎感) */
body:active, a:active, button:active, .mes::after:active {
    cursor: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'%3E%3Cpath fill='%23800000' stroke='%23ffffff' stroke-width='1.5' d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/%3E%3Cpath stroke='%23ffffff' stroke-width='2' d='M12 4 L10 10 L14 14 L11 20' fill='none'/%3E%3C/svg%3E") 12 12, crosshair !important;
}

/* 输入框保留打字机指针，防止影响打字体验 */
input[type="text"], input[type="number"], textarea, .text_pole, #send_textarea {
    cursor: text !important;
}
